"""The druid backend fixture, loaded from a descriptor generated by the real
tdx-system / tdx-domain create path (the compose lifecycle mocked in conftest).
Druid is a `containers` (compose-stack) system; a domain is a datasource."""

from __future__ import annotations

import pytest

from tabsdatax.itest.fixture import backend as common
from tabsdatax.itest.fixture.backends.druid import (
    DruidDomain,
    DruidSystem,
    druid_domain,
    druid_system,
)
from tabsdatax.itest.tdksystems import tdx


def test_druid_system(provision):
    provision.system("druid", "d1")
    obj = common.load("d1", DruidSystem)
    assert isinstance(obj, DruidSystem) and obj.system_type == "druid"
    assert obj.name == "d1" and obj.system_kind == "druid"
    assert obj.project == "tdx_d1"  # the compose project
    assert obj.image.startswith("apache/druid:")
    assert obj.overlord_url.startswith("http://")
    assert obj.router_url.startswith("http://")
    assert obj.user == "admin" and obj.password  # basic-auth admin credentials


def test_druid_domain(provision):
    provision.system("druid", "d1")
    provision.domain("druid", "d1", "events")
    obj = common.load("events", DruidDomain)
    assert isinstance(obj, DruidDomain) and obj.system_type == "druid"
    # The datasource is the prefixed external name (default DOMAIN_PREFIX); the
    # descriptor's logical name stays "events".
    ext = tdx._resolve_domain_prefix(None) + "events"
    assert obj.datasource == ext
    assert obj.overlord_url.startswith("http://")
    assert obj.router_url.startswith("http://")
    assert obj.user == "admin" and obj.password  # inherited from the system


@pytest.fixture
def druid_ready(provision):
    provision.system("druid", "wh")
    provision.domain("druid", "wh", "sales")


@druid_system("wh")
@druid_domain("sales")
def test_druid_injection(
    druid_ready, system_wh: DruidSystem, domain_sales: DruidDomain
):
    assert isinstance(system_wh, DruidSystem)
    assert isinstance(domain_sales, DruidDomain)
    assert system_wh.name == "wh" and domain_sales.name == "sales"
